const r = await tools.shell_command({
  command: "$workspacePath = (Get-Location).Path
Write-Output "--- resolved Git metadata ---"
git rev-parse --absolute-git-dir
git config --get remote.origin.url
git config --get branch.main.remote
git config --get branch.main.merge
Write-Output "--- repository-local Entire indicators ---"
$names = @('.entire', '.entire.json', 'entire.json')
foreach ($name in $names) {
  $candidate = Join-Path $workspacePath $name
  if (Test-Path -LiteralPath $candidate) { Write-Output "$name=present" } else { Write-Output "$name=absent" }
}
Write-Output "--- Entire executable resolution ---"
$cmd = Get-Command entire -All -ErrorAction SilentlyContinue
if ($null -eq $cmd) { Write-Output "ENTIRE_ON_PATH=no" } else { $cmd | Select-Object Name, Source, CommandType | Format-Table -AutoSize }
Write-Output "--- immediate directory relationship ---"
Write-Output "PARENT=$((Get-Item -LiteralPath '..').FullName)"
Write-Output "ROOT_MATCH=$([System.StringComparer]::OrdinalIgnoreCase.Equals($workspacePath, (git rev-parse --show-toplevel).Replace('/', '\')))"",
  workdir: "C:\Code\Projects\APP-StackMap",
  timeout_ms: 10000
});
text(r);
